/* Captura literal da build 1.3.4, antes de extrair estados terminais. Não modificar. */
function die(){if(!G||G.over)return;stopAuto();G.over=true;endMeta(false);deleteStore(SAVE);const p=G.hero;showModal(`<span class="modal-kicker">SUA HISTÓRIA FOI INTERROMPIDA</span><h2>O osso <em>vence.</em></h2><p>A Carcaça conhece mais um nome que nunca alcançou a superfície. Mas o próximo aventureiro pode encontrar sua marca.</p><div class="stat-row"><span>Profundidade alcançada</span><b>${G.floor} / 5</b></div><div class="stat-row"><span>Turnos sobrevividos</span><b>${G.turn}</b></div><div class="stat-row"><span>Inimigos derrotados</span><b>${G.kills}</b></div><div class="stat-row"><span>Âmbar recuperado</span><b>${G.treasure}</b></div><div class="footer-actions"><button id="dead-title">MENU INICIAL</button><button id="dead-again" style="background:#803b40;border-color:#bf6663">OUTRA EXPEDIÇÃO ↺</button></div>`,false);$('dead-title').onclick=()=>{hideModal(true);showScreen('home');};$('dead-again').onclick=()=>{hideModal(true);showScreen('select');renderClasses();};beep(75,.5,'sawtooth');}
function finalDecision(){if(!G||G.over)return;stopAuto();G.over=true;showModal(`<span class="modal-kicker">O NOME SEPULTADO</span><h2>A palavra <em>respira.</em></h2><p>O Escrivão cai. Nas paredes do osso, a última inscrição se acende: <strong>本</strong>, a origem. A Corte tentou apropriar-se do direito de nomear o mundo. Agora ele está diante de você.</p><p>O que fará com esse poder?</p><div class="choices"><button class="choice" id="end-free"><span class="choice-icon">光</span><span class="choice-content"><b>REVELAR O NOME</b><small>Devolver à Carcaça uma verdade compartilhada, impossível de monopolizar.</small></span></button><button class="choice" id="end-hold"><span class="choice-icon">根</span><span class="choice-content"><b>GUARDAR O NOME</b><small>Proteger o segredo até que os povos livres possam decidir seu destino.</small></span></button></div>`,false);$('end-free').onclick=()=>victory('luz');$('end-hold').onclick=()=>victory('raiz');}
function victory(ending){endMeta(true);deleteStore(SAVE);const p=G.hero;const text=ending==='luz'?'A inscrição emerge das catacumbas, gravada em milhares de pequenas pedras. Nenhum trono conseguirá recolher todas. A verdade torna-se pública.':'Você retira a inscrição do altar e a esconde entre os clãs livres. O poder de nomear permanece protegido, até que a própria terra escolha sua voz.';showModal(`<span class="modal-kicker">VITÓRIA · ${ending==='luz'?'O CAMINHO DA LUZ':'O CAMINHO DA RAIZ'}</span><h2>Golzdov <em>se lembra.</em></h2><p>${text}</p><p>Você retorna à superfície. A luta contra a Rainha da Noite não terminou — mas algo que ela julgava possuir já não lhe pertence.</p><div class="stat-row"><span>Classe</span><b>${CLASSES[p.classId].short}</b></div><div class="stat-row"><span>Nível final</span><b>${p.level}</b></div><div class="stat-row"><span>Inimigos derrotados</span><b>${G.kills}</b></div><div class="stat-row"><span>Turnos</span><b>${G.turn}</b></div><div class="footer-actions"><button id="win-menu">MENU INICIAL</button><button id="win-again" style="background:#7a3c3d;border-color:#cb726b">JOGAR NOVAMENTE ↺</button></div>`,false);$('win-menu').onclick=()=>{hideModal(true);showScreen('home');};$('win-again').onclick=()=>{hideModal(true);showScreen('select');renderClasses();};beep(820,.4,'triangle');}
function endMeta(win){const meta=getStore(META,{best:0,wins:0,runs:0,kills:0});meta.best=Math.max(meta.best||0,G.floor);meta.runs=(meta.runs||0)+1;meta.kills=(meta.kills||0)+G.kills;if(win)meta.wins=(meta.wins||0)+1;putStore(META,meta);}
